from pathlib import Path
import os,stat,hashlib,base64,json
BASE=Path('/data1/yanruj');UID=114316761
assert os.getuid()==os.geteuid()==UID and BASE.resolve(strict=True)==BASE and not any(p.is_symlink() for p in (BASE,*BASE.parents))
s=BASE.lstat();assert stat.S_ISDIR(s.st_mode) and s.st_uid==UID and stat.S_IMODE(s.st_mode)==0o700
body=base64.b64decode('',validate=True);assert len(body)==15383 and hashlib.sha256(body).hexdigest()=='9110d17ab02836bc49161ba28d659087f810784eef794502a6c384d607ec8de2'
p=Path('/data1/yanruj/lanl17-read-original-dx100-deployment-prerequisites-20261008-a1-r2.py');assert p.parent==BASE and not os.path.lexists(p)
os.umask(0o077);fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW|os.O_CLOEXEC,0o600)
